{
  "kind": "beast.source_patch.v1",
  "operations": [
    {
      "op": "replace_exact",
      "op_id": "op_001",
      "path": "app/config.py",
      "old": "def parse_bool(value):
    if isinstance(value, bool):
        return value
    if value in {"true", "1", "yes"}:
        return True
    if value in {"false", "0", "no"}:
        return False
    raise ValueError(value)",
      "new": "def parse_bool(value):
    if isinstance(value, bool):
        return value
    value = str(value).strip().lower()
    if value in {"true", "1", "yes", "on"}:
        return True
    if value in {"false", "0", "no", "off"}:
        return False
    raise ValueError(f"Invalid boolean value: {value}")",
      "why": "Normalize boolean values to handle shell-style inputs and improve robustness."
    },
    {
      "op": "replace_exact",
      "op_id": "op_002",
      "path": "app/config.py",
      "old": "gateway_config(env):
    return {
        "provider": env.get("BEAST_PROVIDER"),
        "live_agent": parse_bool(env.get("BEAST_LIVE_AGENT", False)),
        "timeout": int(env.get("BEAST_TIMEOUT", "120")),
    }",
      "new": "d

